const currentScene = game.scenes.active;

const doorSource = await game.modules.get("dylans-general-automations").api.scripts.UserPaintArea();
if (!doorSource) return;

const doorDestination = await game.modules.get("dylans-general-automations").api.scripts.UserPaintArea();
if (!doorDestination) return;

// find a unique teleport name
const existingNames = new Set(currentScene.regions.contents.map(r => r.name));
let name = "Teleport Region";
for (let i = 1; ; i++) {
  if (!existingNames.has(`Teleport Region ${i}`)) {
    name = `Teleport Region ${i}`;
    break;
  }
}

// create the document
const tpData = {
  "elevation": {
    "bottom": 0,
    "top": 20,
    "topInclusive": false
  },
  "levels": [
    "defaultLevel0000"
  ],
  "restriction": {
    "enabled": false,
    "type": "move",
    "priority": 0
  },
  "attachment": {
    "token": null
  },
  "visibility": 2,
  "highlightMode": "shapes",
  "displayMeasurements": false,
  "hidden": false,
  "name": name,
  "shapes": [
    {
      "type": "rectangle",
      "x": doorSource.x,
      "y": doorSource.y,
      "width": currentScene.grid.size,
      "height": currentScene.grid.size,
      "hole": false,
      "anchorX": 0,
      "anchorY": 0,
      "rotation": 0,
      "gridBased": false
    }
  ],
  "behaviors": [],
  "locked": false,
};
const tpAData = foundry.utils.deepClone(tpData);
const tpBData = foundry.utils.deepClone(tpData);
tpAData.shapes[0].x = doorSource.x;
tpAData.shapes[0].y = doorSource.y;
tpBData.shapes[0].x = doorDestination.x;
tpBData.shapes[0].y = doorDestination.y;

const [a,b] = await currentScene.createEmbeddedDocuments("Region", [tpAData, tpBData]);

const tpBehavior = {
  "name": "Teleport Token",
  "type": "teleportToken",
  "system": {
    "destinations": [],
    "placement": "random",
    "snap": true,
    "choice": false,
    "revealed": false,
    "dialog": {
      "revealed": null,
      "unrevealed": null
    },
    "transition": {
      "type": null,
      "duration": 1500
    }
  },
  "disabled": false,
  "flags": {
    "dylans-general-automations": {
      "hasTokenInteract": false
    }
  }
};
const tpBehaviorA = foundry.utils.deepClone(tpBehavior);
tpBehaviorA.system.destinations.push(b.id);
const tpBehaviorB = foundry.utils.deepClone(tpBehavior);
tpBehaviorB.system.destinations.push(a.id);

await a.createEmbeddedDocuments("Behavior", [tpBehaviorA]);
await b.createEmbeddedDocuments("Behavior", [tpBehaviorB]);
